message.content:
{
  "avaliacoes": [
    {
      "criterio": "aderencia_curricular",
      "nota": 2,
      "justificativa": "Conteúdos e objetivos tratam apenas de algoritmos de ordenação, embora a habilidade EF08CO03 exija manipulação clássica de listas de forma mais ampla (inserção, remoção, busca)."
    },
    {
      "criterio": "alinhamento_objetivos",
      "nota": 3,
      "justificativa": "Objetivos específicos são observáveis, distintos e alinhados ao objetivo geral e à habilidade; verbos claros (identificar, simular) permitem observação."
    },
    {
      "criterio": "coerencia_metodologica",
      "nota": 3,
      "justificativa": "Metodologia declarada corresponde às atividades ET1 e ET2; sequência lógica da exposição à prática; tipo de aula teórica respeitado."
    },
    {
      "criterio": "viabilidade",
      "nota": 3,
      "justificativa": "Recursos listados (projetor, computadores) são usados; tempos de 40 e 50 minutos são plausíveis para apresentação e simulação, sem exigir materiais adicionais."
    },
    {
      "criterio": "avaliacao_aprendizagem",
      "nota": 2,
      "justificativa": "Evidências e instrumentos estão ligados aos objetivos, porém os critérios de avaliação são genéricos e não especificam níveis de desempenho, dificultando a discriminação entre respostas adequadas e inadequadas."
    },
    {
      "criterio": "inclusao",
      "nota": 3,
      "justificativa": "Adaptacoes ADP1 e ADP2 oferecem suporte oral e individualizado, mantendo os mesmos recursos e tempo, garantindo participação sem diluir os objetivos."
    }
  ],
  "falhas": [
    {
      "id": "F1",
      "criterio": "aderencia_curricular",
      "componente": "objetivos",
      "gravidade": "maior",
      "descricao": "O plano foca apenas em algoritmos de ordenação, deixando de abordar outros tipos de manipulação de listas previstos na habilidade EF08CO03 (inserção, remoção, busca).",
      "correcao_sugerida": "Ampliar os conteúdos e objetivos para incluir, ao menos brevemente, algoritmos de inserção, remoção e busca, ou reformular a habilidade como foco exclusivo em ordenação."
    },
    {
      "id": "F2",
      "criterio": "avaliacao_aprendizagem",
      "componente": "avaliacao_preliminar",
      "gravidade": "menor",
      "descricao": "Os critérios de avaliação (campo 'criterio' nas evidências) são genéricos e não especificam níveis de desempenho, dificultando a distinção entre desempenho adequado e inadequado.",
      "correcao_sugerida": "Definir rubricas com descritores claros para cada nível (por exemplo, 'responde corretamente a todas as perguntas' vs 'responde parcialmente') e incluir indicadores observáveis."
    }
  ],
  "resumo": "O plano atende bem à maioria dos critérios, apresentando objetivos claros, metodologia coerente, viabilidade e inclusão adequadas. Contudo, cobre apenas a parte de ordenação da habilidade EF08CO03, omitindo outros tipos de manipulação de listas, e os critérios de avaliação carecem de detalhamento rubricado, o que justifica notas 2 nesses aspectos e as falhas apontadas."
}

